function overview(){const team=canTeam(),ids=team?people.map(p=>p.id):[me().id],items=data.history.filter(x=>x.month===state.period&&ids.includes(x.staff)),ongoing=visibleTasks().filter(x=>x.handler&&ids.includes(x.handler)&&x.stage!=='done'),cor=items.filter(x=>x.correction).length;
 return pageHead(team?t('Pekerjaan nyata. Gambaran utuh.','Real work. A clearer picture.'):t(`Ruang kerja ${me().name.split(' ')[0]}.`,`${me().name.split(' ')[0]}’s workspace.`),t('Lihat hasil, tindak lanjut, dan konteks di balik pekerjaan.','See outcomes, follow-ups and the context behind the work.'),periodPicker())+`<div class="strip">${metric(t('Pekerjaan selesai','Completed work'),items.length,month())}${metric(t('Selesai tepat waktu','Completed on time'),items.length?Math.round(items.filter(x=>x.onTime).length/items.length*100)+'%':'—',`${items.filter(x=>x.onTime).length} / ${items.length} ${t('pekerjaan','items')}`)}${metric(t('Perlu koreksi internal','Internal corrections'),cor,t('Lihat penyebab pada rincian','View reasons in the details'))}${metric(t('Tindak lanjut saat ini','Current follow-ups'),ongoing.length,t('Kondisi per 19 September','As of September 19'))}</div>${team?`<section class="panel"><div class="panel-head"><div><h2>${t('Kontribusi tim','Team contributions')}</h2><p>${t('Empat staff · urutan tetap, tanpa ranking','Four staff · fixed order, no ranking')}</p></div>${badge(t('Juli–Agustus tersedia','July–August available'))}</div><div class="table-wrap"><table><thead><tr><th>${t('Staff','Staff')}</th><th>${t('Selesai','Completed')}</th><th>${t('Tepat waktu','On time')}</th><th>${t('Koreksi','Corrections')}</th><th>${t('Tren mingguan','Weekly trend')}</th><th></th></tr></thead><tbody>${people.map(p=>{const m=perf(p.id);return `<tr><td>${personCell(p)}</td><td>${m.total}</td><td>${m.on}/${m.total}</td><td>${m.corrections}</td><td>${spark(p.id)}</td><td>${btn(icon('arrow'),'profile',`data-id="${p.id}" aria-label="${t('Lihat profil','View profile')} ${p.name}"`,'small')}</td></tr>`;}).join('')}</tbody></table></div></section>`:panel(t('Perkembanganmu','Your progress'),`<div class="grid equal">${weeklyChart(me().id)}${typeChart(me().id)}</div>`,btn(t('Profil & Kinerja','Profile & Performance'),'nav','data-page="profile"','text'))}<div class="grid space">${panel(t('Penanganan & hambatan','Handling & blockers'),ongoing.map(taskRow).join('')||empty(t('Tidak ada tindak lanjut saat ini','No current follow-ups')), '',t('Status terkini terpisah dari periode hasil kerja.','Current status is separate from the performance period.'))}${panel(t('Catatan kerja','Work notes'),`<div class="row"><div><strong>${t('Tinjau catatan koreksi','Review correction records')}</strong><small>${t('Rincian metadata dapat ditelusuri pada Profil & Kinerja.','Metadata findings are traceable in Profile & Performance.')}</small></div>${icon('arrow')}</div><div class="row"><div><strong>${t('Menunggu pihak lain','Waiting on others')}</strong><small>${t('Waktu menunggu dipisahkan dari waktu penanganan aktif.','Waiting time is separate from active handling time.')}</small></div>${badge(ongoing.filter(waiting).length)}</div><div class="row"><div><strong>${t('Ulasan bulanan tersedia','Monthly review available')}</strong><small>${t('Ringkasan AI simulasi dengan tautan bukti.','Simulated AI summary with supporting records.')}</small></div></div>`,btn(t('Buka profil saya','Open my profile'),'profile',`data-id="${me().id}"`,'text'))}</div>`;}
