function weeklyChart(id){const a=weekly(perf(id).items),b=state.period==='2026-08'?weekly(perf(id,'2026-07').items,'2026-07'):[0,0,0,0];const max=Math.max(...a,...b,1);return `<div><h3>${t('Hasil dalam empat bagian bulan','Outcomes across four parts of the month')}</h3><div class="chart">${a.map((n,i)=>`<div class="chart-col"><small>${n}</small><div class="chart-bars">${state.period==='2026-08'?`<span class="prev" style="height:${b[i]/max*100}%" title="${t('Juli','July')}: ${b[i]}"></span>`:''}<span class="curr" style="height:${n/max*100}%" title="${n}"></span></div><small>${t('Bagian','Part')} ${i+1}</small></div>`).join('')}</div><div class="legend">${state.period==='2026-08'?`<span><i style="background:var(--hover)"></i>${t('Juli','July')}</span>`:''}<span><i style="background:var(--accent)"></i>${month()}</span></div></div>`;}
