function accessPage(){if(!me().super)return '';return pageHead(t('Akses yang bisa kamu rasakan.','Access you can experience.'),t('Susun role, lalu pratinjau bagaimana Admin bekerja dengannya.','Configure roles, then preview how Admins work with them.'),btn(t('Buat role','Create role'),'role-new','','primary'))+panel(t('Role operasional','Operational roles'),data.roles.map(r=>`<div class="row"><div><strong>${esc(splitLabel(r.name))}</strong><small>${Object.entries(r.rules).filter(([k,v])=>v!=='none').length} ${t('area akses','access areas')}</small></div>${btn(t('Atur & pratinjau','Edit & preview'),'role',`data-id="${r.id}"`,'small')}</div>`).join(''))+`<section class="panel space"><div class="panel-head"><h2>${t('Akun pengguna','User accounts')}</h2><small>${t('4 akun demo','4 demo accounts')}</small></div><div class="table-wrap"><table><thead><tr><th>${t('Nama','Name')}</th><th>${t('Role operasional','Operational role')}</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td>${personCell(p)}</td><td>${p.super?t('Seluruh kewenangan','Full authority'):esc(splitLabel(data.roles.find(r=>r.id===data.assignments[p.id])?.name||t('Belum diberikan','Not assigned')))}</td><td><div class="team-actions">${p.super?'':`${btn(t('Ubah role','Change role'),'assign',`data-id="${p.id}"`,'small')}${btn(icon('eye')+t('Pratinjau','Preview'),'preview',`data-id="${p.id}"`,'small')}`}</div></td></tr>`).join('')}</tbody></table></div></section>${panel(t('Permintaan persetujuan','Approval requests'),data.requests.map(x=>`<div class="row"><div><strong>${person(x.staff).name} · ${esc(splitLabel(x.title))}</strong><small>${esc(x.note||'')}</small></div><div class="inline">${badge(statusName(x.status),x.status==='pending'?'amber':'green')}${x.status==='pending'?`${btn(t('Setujui','Approve'),'request-decision',`data-id="${x.id}" data-value="approved"`,'small')}${btn(t('Tolak','Decline'),'request-decision',`data-id="${x.id}" data-value="rejected"`,'small')}`:''}</div></div>`).join('')||empty(t('Tidak ada permintaan persetujuan','No approval requests')), '',t('Permintaan demo dari tindakan yang membutuhkan approval.','Demo requests from actions that require approval.'))}<p class="scope-note">${t('Pratinjau menguji izin akun tujuan; kewenangan sesi Super Admin tidak diwariskan ke tampilan Admin.','Preview tests the target account’s permissions; the Super Admin session’s authority is not inherited by the Admin view.')}</p>`;}
function settingsPage(){if(!me().super)return '';const p=data.policy;return pageHead(t('Aturan yang mudah dipahami.','Rules that are easy to understand.'),t('Kebijakan berlaku bagi empat staff, termasuk Super Admin.','Policies apply to all four staff, including Super Admins.'))+`<section class="panel pad"><form data-form="policy"><h2>${t('Kehadiran & cuti tahunan','Attendance & annual leave')}</h2><p class="sub">${t('Setiap perubahan memiliki tanggal berlaku dan alasan.','Every change has an effective date and a reason.')}</p><div class="form-grid space">${field('quota',t('Kuota tahunan (hari kerja)','Annual allowance (working days)'),p.quota,'number','min="12" max="60" required')}${field('carry',t('Maksimal sisa dibawa (hari)','Maximum carryover (days)'),p.carry,'number','min="0" max="30" required')}${field('notice',t('Anjuran pengajuan sebelum (hari kerja)','Recommended notice (working days)'),p.notice,'number','min="0" max="30" required')}${field('grace',t('Toleransi keterlambatan (menit)','Late grace period (minutes)'),p.grace,'number','min="0" max="120" required')}${field('start',t('Jam masuk','Work starts'),p.start,'time','required')}${field('end',t('Jam selesai','Work ends'),p.end,'time','required')}${field('effective',t('Berlaku mulai','Effective from'),p.effective,'date','required min="2026-01-01" max="2026-09-19"')}<div class="field"><label>${t('Sisa cuti berlaku sampai','Carryover expiry')}</label><input value="${t('31 Maret tahun berikutnya','March 31 of the following year')}" readonly></div><div class="field full"><label>${t('Hari kerja','Working days')}</label><div class="inline">${t('Sen Sel Rab Kam Jum Sab Min','Mon Tue Wed Thu Fri Sat Sun').split(' ').map((s,i)=>`<label class="check"><input type="checkbox" name="days" value="${(i+1)%7}" ${p.days.includes((i+1)%7)?'checked':''}>${s}</label>`).join('')}</div></div>${reasonField().replaceAll("f-reason","policy-reason")}</div><p class="scope-note">${t('Demo: hak tersedia setelah 12 bulan kerja; semua staff sudah memenuhi syarat. Sakit dan izin khusus tidak mengurangi cuti tahunan. Pengaturan saldo tahun berikutnya dicatat sebagai kebijakan; rollover otomatis di luar demo ini.','Demo: entitlement begins after 12 months; all staff are eligible. Sick and special leave do not reduce annual leave. Next-year carryover is recorded as policy; automated rollover is outside this demo.')}</p>${formEnd(t('Simpan kebijakan','Save policy'))}</form></section><div class="grid equal space">${panel(t('Kalender libur','Holiday calendar'),data.holidays.map(d=>`<div class="row"><span>${date(d)}</span>${badge(t('Libur','Holiday'))}</div>`).join(''),btn(t('Tambah tanggal','Add date'),'holiday','','text'))}${panel(t('Penilaian kinerja','Performance assessment'),`<p class="sub">${t('Hasil, ketepatan waktu, dan alasan koreksi diperlihatkan terpisah. Tidak ada target, ranking, atau skor gabungan.','Outcomes, timeliness and correction reasons are shown separately. No targets, rankings or composite scores.')}</p><div class="row"><span>${t('Ulasan AI','AI review')}</span>${badge(t('Contoh berbasis data demo','Demo-record example'),'blue')}</div><div class="row"><span>${t('Keputusan bonus','Bonus decisions')}</span><strong>Super Admin</strong></div>`)}</div>`;}
function logsPage(){if(!me().super)return '';return issuePanel()+pageHead(t('Riwayat perubahan','Change history'),t('Perubahan dalam sesi ini, dengan pelaku dan alasannya.','Changes in this session, with actors and reasons.'))+panel(t('Catatan sesi','Session log'),data.logs.map(x=>`<div class="activity"><span class="eventdot"></span><div class="grow"><strong>${x.who}</strong><p>${esc(x.text)}</p><small>${esc(x.reason||'')}</small></div><time>${x.time}</time></div>`).join('')||empty(t('Belum ada perubahan dalam sesi ini','No changes in this session')));}
let restoreFocus=null,toastTimer;
function modal(title,body,wide=false){const d=$('#dialog');if(!d.open)restoreFocus=document.activeElement;d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${state.preview?`<small>${t("Pratinjau sebagai","Preview as")} ${me().name} · ${t("simulasi tanpa perubahan data","simulation without data changes")}</small>`:""}</div><button type="button" class="iconbtn" data-action="close" aria-label="${t('Tutup','Close')}">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){const d=$('#dialog');if(d.open)d.close();d.innerHTML='';if(restoreFocus?.isConnected)restoreFocus.focus();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
function feedback(s){const el=$('#form-feedback')||$('#preview-feedback');if(el)el.innerHTML=`<div class="preview-feedback" role="status">${s}</div>`;toast(s.replace(/<[^>]+>/g,' '));}
function log(text,reason=''){data.logs.unshift({who:me().name,text,reason,time:'19 Sep · 12.00'});}
function previewBlocked(approval=false){if(!state.preview)return false;feedback(approval?t('Memerlukan persetujuan Super Admin. Permintaan akan menunggu keputusan. Mode pratinjau: tidak ada permintaan dikirim dan tidak ada data utama berubah.','Super Admin approval required. The request would await a decision. Preview mode: no request sent and no main data changed.'):t('Tindakan ini diizinkan bagi akun yang dipreview. Hasil disimulasikan; tidak ada data utama berubah.','This action is allowed for the previewed account. The outcome is simulated; no main data changed.'));return true;}
function go(page,mode){closeModal();if(mode)state.mode=mode;state.page=page;state.mobile=false;if(page==='profile')state.profile=null;render();window.scrollTo({top:0});$('#main').focus({preventScroll:true});}
function taskModal(id){const x=visibleTasks().find(x=>x.id===id);if(!x)return toast(t('Objek tidak tersedia pada cakupan ini.','This object is not available in this scope.'));modal(esc(splitLabel(x.title)),`${badge(x.id)} ${badge(stageName(x.stage),waiting(x)?'amber':'blue')}<p class="sub">${x.label} · ${L(kinds[x.kind])}</p>${x.stage!=='queued'?`${progress(x.pct)}<p class="scope-note">${x.pct==null?t('Penanganan tercatat; belum ada persentase tahapan yang terukur.','Handling is recorded; no measurable stage percentage yet.'):t('Persentase menunjukkan tahapan proses, bukan waktu kerja.','Percentage reflects workflow stages, not working time.')}</p>`:''}${x.overdue?`<div class="notice space">${L(x.reason)}</div>`:''}<h3 class="space">${t('Riwayat penanganan','Handling history')}</h3><ol class="timeline space"><li>${t('Label mengajukan pekerjaan','Label submitted the work')}<small>${t('Masuk antrean; belum dianggap dikerjakan staff.','Entered the queue; not counted as staff work yet.')}</small></li>${x.handler?`<li>${person(x.handler).name} · ${t('Tindakan bisnis tersimpan','Business action saved')}<small>${date(x.last)} · ${x.last.slice(11,16)} · ${t('Bukti terakhir, bukan bukti sedang online.','Last evidence, not proof of being online.')}</small></li>`:''}${data.events.filter(e=>e.obj===x.id).slice(0,3).map(e=>`<li>${esc(L(e.text))}<small>${e.who?person(e.who).name:x.label} · ${e.time}</small></li>`).join('')}</ol><div class="notice space">${t('Ringkasan modul Part 2. Di sini kamu dapat mencoba satu tindakan bisnis simulasi, tanpa koneksi ke rilismusik.com.','Part 2 module summary. You can try a simulated business action here, without connecting to rilismusik.com.')}</div>${x.stage!=='done'?`<form data-form="task-action" data-id="${x.id}"><div class="field"><label for="f-note">${t('Catatan pemeriksaan / hasil tindakan','Review note / action result')}</label><textarea id="f-note" name="note" required maxlength="500" placeholder="${t('Jelaskan hasil pemeriksaan yang dilakukan…','Describe the review outcome…')}"></textarea></div>${formEnd(x.stage==='queued'?t('Simpan hasil pemeriksaan','Save review findings'):x.stage==='believe'?t('Konfirmasi tayang · simulasi','Confirm live · simulation'):t('Simpan & lanjutkan tahapan','Save & advance stage'))}</form>`:''}`);}
function queueModal(kind){let tasks=visibleTasks().filter(x=>kind==='overdue'?x.overdue&&x.stage!=='done':x.kind===kind&&x.stage==='queued');modal(kind==='overdue'?t('Perlu tindak lanjut','Needs follow-up'):L(kinds[kind]||[kind,kind]),tasks.map(x=>`<div class="row"><div><strong>${esc(splitLabel(x.title))}</strong><small>${x.label} · ${stageName(x.stage)}</small></div>${btn(t('Lihat','View'),'task',`data-id="${x.id}"`,'small')}</div>`).join('')||empty(t('Antrean ini sudah kosong','This queue is empty')));}
function historyModal(id,correction=false){if(!canTeam()&&id!==me().id)return;const p=person(id),a=perf(id).items.filter(x=>!correction||x.correction);modal(`${t('Catatan pekerjaan','Work records')} · ${p.name}`,`<p class="sub">${month()} · ${a.length} ${t('catatan','records')}</p><div class="table-wrap space"><table><thead><tr><th>${t('Pekerjaan','Work')}</th><th>${t('Selesai','Completed')}</th><th>${t('Catatan','Notes')}</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td>${esc(splitLabel(x.title))}<small>${L(kinds[x.kind])}</small></td><td>${date(x.completed)}</td><td>${x.correction?badge(t('Koreksi metadata','Metadata correction'),'amber'):badge(t('Selesai','Completed'),'green')}</td><td>${btn(icon('arrow'),'history-detail',`data-id="${x.id}" aria-label="${t('Buka rincian','Open details')} ${esc(splitLabel(x.title))}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`,true);}
function historyDetail(id){const x=data.history.find(x=>x.id===id);if(!x||(!canTeam()&&x.staff!==me().id))return;modal(esc(splitLabel(x.title)),`${badge(L(kinds[x.kind]))}<dl class="facts space"><div><dt>${t('Penyelesai tahapan','Stage completed by')}</dt><dd>${person(x.staff).name}</dd></div><div><dt>${t('Waktu penyelesaian','Completion time')}</dt><dd>${date(x.completed)} · ${x.completed.slice(11,16)} WIB</dd></div><div><dt>${t('Ketepatan waktu','Timeliness')}</dt><dd>${x.onTime?t('Dalam batas waktu','Within deadline'):t('Melewati batas waktu','Past deadline')}</dd></div><div><dt>${t('Hasil','Outcome')}</dt><dd>${t('Tahapan selesai','Stage completed')}</dd></div></dl>${x.correction?`<div class="notice space"><strong>${t('Koreksi internal: kelengkapan metadata','Internal correction: metadata completeness')}</strong><p>${t('Kolom pemegang hak belum lengkap saat pemeriksaan pertama. Diperbaiki sebelum tahapan diselesaikan.','The rights-holder field was incomplete at first review. Corrected before this stage was completed.')}</p></div>`:''}<div class="notice space">${t('Durasi kerja aktif tidak tersedia. Catatan ini membuktikan hasil tahapan, bukan seluruh durasi penanganan.','Active working duration is unavailable. This record establishes the stage outcome, not the full handling duration.')}</div><small>${esc(x.id)} · ${t('Data simulasi','Simulated data')}</small>`);}
function leaveModal(){modal(t('Ajukan cuti atau izin','Request leave or time off'),`<form data-form="leave"><div class="form-grid">${selectField('type',t('Jenis pengajuan','Request type'),[['annual',t('Cuti tahunan','Annual leave')],['sick',t('Sakit','Sick leave')],['special',t('Izin khusus','Special leave')]],'annual')}${field('start',t('Mulai','Start'),'','date',`required min="${day()}" max="${day().slice(0,4)}-12-31"`)}${field('end',t('Selesai','End'),'','date',`required min="${day()}" max="${day().slice(0,4)}-12-31"`)}${reasonField()}</div><div id="leave-estimate" class="notice space">${t('Pilih tanggal untuk menghitung hari kerja.','Select dates to count working days.')}</div><p class="scope-note">${t('Pengajuan tahunan yang menunggu akan mencadangkan saldo. Pengajuan mendesak tetap dapat dikirim dengan alasan.','Pending annual leave reserves your balance. Urgent requests can still be submitted with a reason.')}</p>${formEnd(t('Kirim pengajuan','Submit request'))}</form>`);}
function estimateLeave(){const f=$('form[data-form="leave"]');if(!f)return;const v=new FormData(f),n=countDays(v.get('start'),v.get('end')),annual=v.get('type')==='annual';$('#leave-estimate').textContent=n?`${n} ${t('hari kerja','working days')} · ${annual?t(`Tersedia setelah pengajuan: ${leaveBalance(me().id).available-n} hari.`,`Available after request: ${leaveBalance(me().id).available-n} days.`):t('Tidak mengurangi cuti tahunan.','Does not reduce annual leave.')}`:t('Pilih rentang tanggal yang memuat hari kerja.','Choose a date range that includes working days.');}
function roleModal(id){if(!me().super||state.preview)return;const r=data.roles.find(r=>r.id===id)||{id:'new',name:'',rules:{}};modal(t('Atur role operasional','Configure operational role'),`<form data-form="role" data-id="${r.id}">${field('name',t('Nama role','Role name'),r.name,'text','required maxlength="70"')}<div class="space">${Object.entries(permissionNames).map(([k,s])=>`<div class="permission-row"><label for="rule-${k}">${L(s)}</label><select id="rule-${k}" name="rule-${k}">${[['none',t('Tidak ada akses','No access')],['direct',t('Diizinkan langsung','Direct access')],...(k==='team'?[]:[['approval',t('Butuh persetujuan','Approval required')]])].map(([v,l])=>`<option value="${v}" ${r.rules[k]===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}</div><p class="scope-note">${t('Tanpa akses: tidak muncul. Butuh approval: tindakan muncul dan mengajukan permintaan. Akses langsung: tindakan tersedia.','No access: hidden. Approval required: visible action submits a request. Direct access: action available.')}</p><div class="inline space"><select id="preview-target" aria-label="${t('Akun untuk preview','Preview account')}" style="width:auto">${people.filter(p=>!p.super).map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select>${btn(icon('eye')+t('Pratinjau rancangan','Preview draft'),'preview-draft','','small')}</div>${formEnd(t('Simpan role','Save role'))}</form>`);}
function enterPreview(id,draft){if(!actor().super||state.preview||person(id)?.super)return;state.preview={target:id,draft:draft||null};state.mode='platform';state.page='dashboard';state.scope='mine';state.profile=null;closeModal();render();window.scrollTo({top:0});toast(t('Preview aktif. Coba tindakan pada rincian pembayaran untuk melihat perilaku approval.','Preview active. Try an action in payment details to see approval behavior.'));}
function paymentModal(){if(permission('finance')==='none')return;modal(t('Rincian pembayaran','Payment details'),`<div class="row"><div><strong>INV-084 · Senja Records</strong><small>${t('Layanan distribusi · contoh transaksi','Distribution service · sample transaction')}</small></div><strong>${money(150000)}</strong></div><div class="notice space">${t('Contoh perubahan catatan transaksi. Data ini terpisah dari kompensasi staff.','Example transaction-note change. This data is separate from staff compensation.')}</div>${data.paymentNote?`<div class="notice">${t("Catatan tersimpan","Saved note")}: ${esc(data.paymentNote)}</div>`:""}<form data-form="payment-action">${reasonField()}${formEnd(t('Ajukan penyesuaian catatan','Request a note adjustment'))}</form>`);}
function searchModal(){modal(t('Pencarian cepat','Quick search'),`<input id="search-input" type="search" autocomplete="off" placeholder="${t('Judul rilisan, nama staff, nomor transaksi…','Release title, staff name, transaction number…')}" aria-label="${t('Cari','Search')}"><p class="scope-note">${t('Mencari data demo dan halaman V3. Nominal kompensasi tidak ditampilkan.','Searches demo data and V3 pages. Compensation amounts are not shown.')}</p><div id="search-results" class="search-results"></div>`);searchResults('');$('#search-input').focus();}
function searchResults(q){q=q.trim().toLocaleLowerCase();const results=[...nav().map(([p,i])=>({label:pages()[p],sub:t('Menu · Staff / Platform','Menu · Staff / Platform'),action:'search-nav',attrs:`data-page="${p}"`,icon:i})),...visibleTasks().map(x=>({label:splitLabel(x.title),sub:`${x.id} · ${x.label}`,action:'task',attrs:`data-id="${x.id}"`,icon:x.kind})),...(canTeam()?people:[me()]).map(p=>({label:p.name,sub:t('Staff · Profil & Kinerja','Staff · Profile & Performance'),action:'profile',attrs:`data-id="${p.id}"`,icon:'user'})),...(permission('finance')!=='none'?[{label:'INV-084',sub:'Senja Records · '+t('Pembayaran layanan','Service payment'),action:'payment-detail',attrs:'',icon:'wallet'}]:[])].filter(x=>(x.label+' '+x.sub).toLocaleLowerCase().includes(q));$('#search-results').innerHTML=results.slice(0,18).map(x=>`<button class="search-result" data-action="${x.action}" ${x.attrs}>${icon(x.icon)}<span><strong>${esc(x.label)}</strong><small>${esc(x.sub)}</small></span>${icon('chevron')}</button>`).join('')||empty(t('Tidak ada hasil','No results'),t('Coba judul, ID, atau nama lain.','Try another title, ID or name.'));}
function notificationModal(){modal(t('Notifikasi','Notifications'),`<p class="sub">${t('Perubahan yang perlu kamu ketahui. Membaca tidak menyelesaikan pekerjaan.','Changes you should know about. Reading does not complete work.')}</p>${visibleNotifications().map(n=>`<div class="activity"><span class="eventdot" style="opacity:${n.read.includes(me().id)?'.2':'1'}"></span><button data-action="notification-open" data-id="${n.id}"><strong>${L(n.title)}</strong><p>${L(n.body)}</p><small>${n.time} · ${n.read.includes(me().id)?t('Dibaca','Read'):t('Belum dibaca','Unread')}</small></button></div>`).join('')}`);}
function chatModal(){if(state.chat==='label'&&permission('support')==='none')state.chat='internal';const label=state.chat==='label',a=data.chats[state.chat];modal('Chat',`<div class="chat-layout"><div class="chat-list">${permission('support')!=='none'?`<button data-action="chat-tab" data-value="label" class="${label?'active':''}">Senja Records<small>${t('Label · Tiket T-318','Label · Ticket T-318')}</small></button>`:''}<button data-action="chat-tab" data-value="internal" class="${!label?'active':''}">${t('Koordinasi internal','Internal coordination')}<small>${t('Catatan terkait rilisan','Release-related notes')}</small></button></div><div><div class="spread"><h3>${label?'Senja Records':t('Koordinasi internal','Internal coordination')}</h3>${permission(label?'support':'release')!=='none'?btn(label?'T-318':'R-1055','task',`data-id="${label?'T-318':'R-1055'}"`,'text'):''}</div><div class="messages">${a.map(x=>`<div class="message ${x.who===me().id?'mine':''}"><small>${person(x.who)?.name||esc(x.who)}</small>${esc(L(x.text))}</div>`).join('')}</div><form data-form="chat" class="chat-send"><input name="message" required maxlength="500" aria-label="${t('Pesan','Message')}" placeholder="${t('Tulis pesan simulasi…','Write a simulated message…')}"><button type="submit" class="btn primary">${t('Kirim','Send')}</button></form><div id="form-feedback" role="status"></div><p class="scope-note">${t('Percakapan demo lokal. Tidak ada pesan yang dikirim ke orang lain.','Local demo conversation. No messages are sent to anyone.')}</p></div></div>`,true);}
function staffPayModal(id){if(!me().super)return;const p=person(id),next=data.nextComp?.[id];modal(t('Kompensasi','Compensation')+' · '+p.name,`${next?`<div class="notice">${t('Perubahan mendatang','Upcoming change')}: ${date(next.effective)}<br>${t('Gaji tetap','Base salary')} ${money(next.salary)} · ${t('Tunjangan','Allowance')} ${money(next.allowance)} · ${t('Bonus penjualan','Sales bonus')} ${next.percent}%</div>`:''}${payments(id).map(x=>`<div class="row"><div><strong>${x.label}</strong><small>${money(x.amount)} · ${date(x.date)}</small></div>${x.paid?badge(t('Dibayar','Paid'),'green'):btn(t('Catat pembayaran','Record payment'),'pay-component',`data-id="${id}" data-key="${x.key}"`,'small')}</div>`).join('')}<div class="inline space">${btn(t('Atur gaji & bonus','Edit salary & bonus'),'salary',`data-id="${id}"`,'small')}${btn(t('Unduh slip','Download payslip'),'payslip',`data-id="${id}"`,'small')}</div>`);}
async function downloadDocument(id,kind,m=state.period){if(id!==me().id&&!me().super)return toast(t('Dokumen ini tidak tersedia.','This document is unavailable.'));if(state.preview){toast(t('Preview: unduhan data pribadi tidak dibuat.','Preview: no personal-data download is generated.'));return;}const p=person(id),pdf=await PDFLib.PDFDocument.create(),font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica),bold=await pdf.embedFont(PDFLib.StandardFonts.HelveticaBold);let page=pdf.addPage([595,842]),y=790;const line=(s,size=11,b=false)=>{const f=b?bold:font,words=String(s).replace(/[^\x20-\x7E]/g,' ').split(' ');let row='';const draw=()=>{if(y<55){page=pdf.addPage([595,842]);y=790;}page.drawText(row,{x:48,y,size,font:f,color:PDFLib.rgb(.15,.15,.15)});y-=size+13;};for(const word of words){const next=row?row+' '+word:word;if(f.widthOfTextAtSize(next,size)>490&&row){draw();row=word;}else row=next;}if(row)draw();};line('RILIS MUSIK',19,true);line('SIMULASI / DEMONSTRATION - NOT AN OFFICIAL DOCUMENT',9);line(kind==='contract'?t('RINGKASAN KONTRAK KERJA','EMPLOYMENT CONTRACT SUMMARY'):t('SLIP KOMPENSASI','COMPENSATION STATEMENT'),15,true);line(p.name+' / '+personLabel(p));if(kind==='contract'){line('PKWTT / '+t('Status: Aktif','Status: Active'));line(t('Bergabung: ','Joined: ')+date(p.joined));line(t('Dokumen contoh untuk demonstrasi tata letak.','Sample document to demonstrate layout.'));line(t('Bukan perjanjian kerja dan tidak memiliki tanda tangan.','Not an employment agreement; no signatures.'));}else{const rows=payments(id,m),total=rows.reduce((n,x)=>n+x.amount,0),paid=rows.filter(x=>x.paid).reduce((n,x)=>n+x.amount,0);line(t('Periode: ','Period: ')+month(m));line('ID: DEMO-'+id.toUpperCase()+'-'+m);y-=10;rows.forEach(x=>{line(x.label+' | IDR '+x.amount.toLocaleString('en-US'),12,true);line(`${x.date} | ${x.paid?t('Dibayar','Paid'):t('Belum dibayar','Unpaid')}`,10);});y-=12;line(t('TOTAL PENDAPATAN: ','TOTAL EARNINGS: ')+'IDR '+total.toLocaleString('en-US'),12,true);line(t('SUDAH DIBAYAR: ','PAID: ')+'IDR '+paid.toLocaleString('en-US'));line(t('BELUM DIBAYAR: ','UNPAID: ')+'IDR '+(total-paid).toLocaleString('en-US'));line(t('Bonus penjualan: ','Sales bonus: ')+data.bonusRules[id]+'% x IDR '+data.revenue[m].toLocaleString('en-US'));}line(t('Data buatan. Tidak ada transfer uang atau dokumen resmi.','Fictional data. No funds transferred or official documents issued.'),9);const bytes=await pdf.save(),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`Rilis-Musik-DEMO-${kind}-${id}-${m}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(t('PDF simulasi berhasil dibuat.','Simulated PDF created.'));}
function issuePanel(){return data.issues.length?panel(t('Laporan data kinerja','Performance data reports'),data.issues.map(x=>`<div class="row"><div><strong>${person(x.staff).name} · ${month(x.period)}</strong><small>${esc(x.reason)}</small></div>${badge(t('Perlu tinjauan','Needs review'),'amber')}</div>`).join('')):'';}
function showPolicy(){modal(t('Kebijakan cuti · demo','Leave policy · demo'),`<div class="row"><span>${t('Kuota tahunan','Annual allowance')}</span><strong>${data.policy.quota} ${t('hari kerja','working days')}</strong></div><div class="row"><span>${t('Syarat masa kerja','Service requirement')}</span><strong>${t('12 bulan','12 months')}</strong></div><div class="row"><span>${t('Periode','Period')}</span><strong>${t('Januari–Desember','January–December')}</strong></div><div class="row"><span>${t('Sisa dibawa','Carryover')}</span><strong>${data.policy.carry} ${t('hari · sampai 31 Maret','days · until March 31')}</strong></div><div class="row"><span>${t('Anjuran pemberitahuan','Recommended notice')}</span><strong>${data.policy.notice} ${t('hari kerja','working days')}</strong></div><p class="sub">${t('Pengajuan mendesak tetap dapat dikirim. Hari libur dan hari di luar jadwal tidak mengurangi saldo. Sakit dan izin khusus ditinjau terpisah. Seluruh staff demo telah bekerja lebih dari 12 bulan.','Urgent requests can still be submitted. Holidays and non-working days do not reduce the balance. Sick and special leave are reviewed separately. All demo staff have more than 12 months of service.')}</p><p class="sub">${t('12 hari adalah dasar simulasi cuti tahunan. Aturan carryover dan waktu pengajuan adalah contoh kebijakan perusahaan.','12 days is the simulated annual leave baseline. Carryover and notice are example company policies.')}</p><p class="scope-note">${t('Berlaku mulai','Effective from')}: ${date(data.policy.effective)}</p>`);}
function addNotification(target,title,body,page){data.notifications.unshift({id:'N'+(data.notifications.length+1),target,title,body,page,time:'12.00',read:[]});}
function outcomeTask(x,note){const stages=x.kind==='release'?{queued:['review',null],review:['approval',50],approval:['believe',75],correction:['review',25],believe:['done',100]}:{queued:['review',null],review:['done',100]};const [stage,pct]=stages[x.stage]||['done',100];x.stage=stage;x.pct=pct;x.handler=me().id;x.last='2026-09-19T12:00:00';x.overdue=false;data.events.unshift({id:Date.now(),who:me().id,obj:x.id,text:[note,note],time:'12.00',category:'work'});log(`${x.id} · ${stageName(stage)}`,note);}
function applyOperation(op){if(op.type==='task'){const x=data.tasks.find(x=>x.id===op.id);if(!x||x.stage!==op.expected)return false;outcomeTask(x,op.note);return true;}if(op.type==='payment'){data.paymentNote=op.note;log(t('Catatan pembayaran diperbarui · INV-084','Payment note updated · INV-084'),op.note);return true;}return false;}
function doOperation(permissionKey,title,op){const mode=permission(permissionKey);if(mode==='none')return feedback(t('Tindakan tidak tersedia.','Action unavailable.'));if(previewBlocked(mode==='approval'))return;if(mode==='approval'){if(data.requests.some(x=>x.staff===me().id&&x.status==='pending'&&x.op.type===op.type&&x.op.id===op.id))return feedback(t('Permintaan yang sama masih menunggu keputusan.','The same request is already pending.'));data.requests.unshift({id:'A'+(data.requests.length+1),staff:me().id,title,note:op.note,status:'pending',op});log(t('Mengirim permintaan persetujuan','Submitted approval request'),title);closeModal();render();toast(t('Permintaan menunggu persetujuan Super Admin. Data belum berubah.','Request pending Super Admin approval. The underlying record has not changed.'));}else{if(!applyOperation(op))return feedback(t('Status telah berubah. Buka ulang pekerjaan sebelum melanjutkan.','The status has changed. Reopen the work before continuing.'));closeModal();render();toast(t('Tindakan tersimpan dalam simulasi.','Action saved in the simulation.'));}}
function personalModal(id){if(id!==me().id&&!canTeam())return;const p=person(id),v=data.profiles[id],editable=id===me().id||me().super;modal(t('Informasi pribadi','Personal information')+' · '+p.name,`<div class="notice">${t('Kontak dan portrait adalah data contoh. Tidak memuat dokumen identitas atau rekening nyata.','Contact and portrait are sample data. No real identity documents or bank details.')}</div><form data-form="personal" data-id="${id}"><div class="form-grid">${field('name',t('Nama','Name'),p.name,'text','readonly')}${field('email','Email',p.email,'email','readonly')}${field('phone',t('Telepon','Phone'),v.phone,'text',editable?'required maxlength="30"':'readonly')}${field('location',t('Lokasi','Location'),v.location,'text',editable?'required maxlength="80"':'readonly')}</div>${editable?`<div class="field space"><label for="photo">${t('Ganti portrait demo (opsional)','Change demo portrait (optional)')}</label><input id="photo" name="photo" type="file" accept="image/png,image/jpeg,image/webp"><small>${t('Disimpan hanya di memori tab · maksimal 2 MB.','Stored only in tab memory · maximum 2 MB.')}</small></div>${formEnd()}`:''}</form>`);}
function guide(){modal(t('Selamat datang di V3','Welcome to V3'),`<p class="sub">${t('Prototype mandiri dengan empat akun. Semua perubahan bisnis berada di memori tab; muat ulang untuk mengembalikan data awal.','Standalone prototype with four accounts. All business changes live in tab memory; reload to restore initial data.')}</p><ol style="font-size:13px;line-height:2;padding-left:20px"><li>${t('Coba Platform → Staff; setiap perpindahan membuka menu pertama.','Try Platform → Staff; switching always opens the first menu.')}</li><li>${t('Pilih Adovi untuk Profil & Kinerja dan contoh ulasan AI.','Choose Adovi for Profile & Performance and an example AI review.')}</li><li>${t('Pilih Cantika untuk saldo cuti 5 hari dan riwayat pengajuan.','Choose Cantika for a 5-day leave balance and request history.')}</li><li>${t('Sebagai Super Admin: Akun & Akses → Atur & pratinjau.','As Super Admin: Accounts & Access → Edit & preview.')}</li><li>${t('Pada preview, buka pencarian INV-084 dan coba perubahan catatan untuk melihat approval.','In preview, search INV-084 and try editing its note to experience approval.')}</li><li>${t('Unduh slip PDF di Kompensasi. Coba bonus tambahan dan pengumumannya melalui Kelola tim.','Download a PDF payslip in Compensation. Try an extra bonus and its announcement in Manage team.')}</li></ol><div class="notice">${t('Riwayat kinerja: Juli–Agustus 2026. Kondisi antrean dan pengajuan: 19 September. Ulasan AI merupakan contoh yang disusun dari catatan demo, bukan koneksi AI langsung.','Performance history: July–August 2026. Queue and requests: September 19. AI reviews are examples based on demo records, not a live AI connection.')}</div><div class="inline">${btn(t('Atur ulang simulasi','Reset simulation'),'reset','','small')}${btn(t('Mulai menjelajah','Start exploring'),'close','','primary')}</div>`);}
async function handleAction(b){const a=b.dataset.action,id=b.dataset.id,value=b.dataset.value;
 if(a==='close')return closeModal();
 if(a==='mode'){state.mode=b.dataset.mode;state.page=state.mode==='platform'?'dashboard':'overview';state.profile=null;state.mobile=false;state.scope='mine';closeModal();render();window.scrollTo({top:0});return;}
 if(a==='nav'||a==='search-nav'){const page=b.dataset.page;return go(page,page==='dashboard'?'platform':'staff');}
 if(a==='mobile'){state.mobile=!state.mobile;render();return;}
 if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';document.documentElement.classList.add('theme-changing');document.documentElement.dataset.theme=state.theme;b.setAttribute('aria-checked',String(state.theme==='dark'));savePrefs();setTimeout(()=>document.documentElement.classList.remove('theme-changing'),300);return;}
 if(a==='lang'){state.lang=state.lang==='id'?'en':'id';savePrefs();render();return;}
 if(a==='guide')return guide();
 if(a==='search')return searchModal();
 if(a==='notifications')return notificationModal();
 if(a==='notification-open'){const n=visibleNotifications().find(n=>n.id===id);if(!n)return;if(!state.preview&&!n.read.includes(me().id))n.read.push(me().id);if(n.obj)return taskModal(n.obj);go(n.page,'staff');return;}
 if(a==='chat')return chatModal();
 if(a==='chat-tab'){state.chat=value;return chatModal();}
 if(a==='account')return modal(t('Akun saya','My account'),`${personCell(me())}<div class="row space"><span>${t('Ketersediaan','Availability')}</span>${badge(t('Online · bukan absensi','Online · not attendance'),'green')}</div><div class="inline space">${btn(t('Buka profil','Open profile'),'profile',`data-id="${me().id}"`,'primary')}${btn(t('Preferensi & bantuan','Preferences & help'),'guide','','small')}</div><p class="scope-note">${t('Tidak ada login nyata pada prototipe. Gunakan kontrol demo untuk mencoba akun lain.','No real login in this prototype. Use demo controls to try another account.')}</p>`);
 if(a==='queue')return queueModal(b.dataset.kind);
 if(a==='task')return taskModal(id);
 if(a==='scope'){state.scope=value;render();return;}
 if(a==='progress-filter'){state.progress=value;render();return;}
 if(a==='activity'){state.activity='all';return activityModal();}
 if(a==='activity-filter'){state.activity=value;return activityModal();}
 if(a==='metrics')return modal(t('Definisi ringkasan','Summary definitions'),`<div class="row"><div><strong>${t('Pendapatan layanan','Service revenue')}</strong><small>${t('Pembayaran Xendit berstatus dibayar pada periode Agustus.','Xendit payments marked paid during August.')}</small></div></div><div class="row"><div><strong>${t('Penarikan periode ini','Withdrawals this period')}</strong><small>${t('Menggabungkan penarikan menunggu dan yang sudah dibayar; bukan seluruhnya tagihan belum lunas.','Combines pending and paid withdrawals; it is not an unpaid-only total.')}</small></div></div><div class="row"><div><strong>${t('Royalti','Royalties')}</strong><small>${t('Laporan impor terakhir: Juni 2026. Tidak otomatis mengikuti bulan kalender saat ini.','Latest imported report: June 2026. Does not automatically follow the current calendar month.')}</small></div></div><p class="sub">${t('Total katalog adalah total terkini; angka tambahan menunjukkan pertambahan selama Agustus. Semua angka adalah data contoh, bukan respons API langsung.','Catalog totals are current totals; additions refer to August. All figures are examples, not live API responses.')}</p>${permission('finance')!=='none'?`<div class="space">${btn(t('Lihat transaksi contoh','View sample transaction'),'payment-detail','','small')}</div>`:''}`);
 if(a==='payment-detail')return paymentModal();
 if(a==='profile'){if(id!==me().id&&!canTeam())return;closeModal();state.profile=id||me().id;state.mode='staff';state.page='profile';render();window.scrollTo({top:0});return;}
 if(a==='history')return historyModal(id,b.dataset.filter==='correction');
 if(a==='history-detail')return historyDetail(id);
 if(a==='personal')return personalModal(id);
 if(a==='contract'){if(id!==me().id&&!canTeam())return;return modal(t('Dokumen kerja','Work documents'),`<div class="row"><div><strong>${person(id).name} · PKWTT</strong><small>${t('Status aktif · bergabung','Active · joined')} ${date(person(id).joined)}</small></div>${badge(t('Simulasi','Simulation'))}</div><p class="sub">${t('Contoh ringkasan hubungan kerja. Dokumen ini bukan kontrak resmi atau nasihat hukum.','Sample employment summary. This is not an official contract or legal advice.')}</p>${id===me().id||me().super?`<div class="space">${btn(icon('download')+t('Unduh contoh PDF','Download sample PDF'),'contract-download',`data-id="${id}"`,'primary')}</div>`:''}`);}
 if(a==='contract-download')return downloadDocument(id,'contract');
 if(a==='data-issue')return modal(t('Laporkan data tidak sesuai','Report a data issue'),`<form data-form="data-issue" data-id="${id}"><p class="sub">${t('Sebutkan pekerjaan dan bagian catatan yang perlu diperiksa.','Identify the work item and the record that needs review.')}</p>${reasonField()}${formEnd(t('Kirim catatan','Submit note'))}</form>`);
 if(a==='attendance-tab'){state.attendance=value;render();return;}
 if(a==='leave')return leaveModal();
 if(a==='policy')return showPolicy();
 if(a==='leave-reject'){if(!me().super)return;return modal(t('Alasan keputusan','Decision reason'),`<form data-form="leave-reject" data-id="${id}">${reasonField()}${formEnd(t('Tolak pengajuan','Decline request'))}</form>`);}
 if(a==='leave-decision'||a==='leave-cancel'){const x=data.leaves.find(x=>x.id===id);if(!x||x.status!=='pending'||(a==='leave-decision'?!me().super:x.staff!==me().id))return;if(previewBlocked())return;x.status=a==='leave-cancel'?'cancelled':'approved';log(t('Status pengajuan cuti berubah','Leave request status changed'),id+' · '+statusName(x.status));if(a==='leave-decision')addNotification(x.staff,['Keputusan cuti tersedia','Leave decision available'],['Buka pengajuan untuk melihat hasilnya.','Open your request to see the decision.'],'attendance');render();toast(t('Status pengajuan diperbarui.','Request status updated.'));return;}
 if(a==='attendance-correction')return modal(t('Ajukan koreksi kehadiran','Request attendance correction'),`<form data-form="attendance-correction"><div class="form-grid">${field('date',t('Tanggal catatan','Record date'),'2026-08-19','date','required min="2026-07-01" max="2026-09-19"')}${selectField('status',t('Status yang benar','Correct status'),[['present',t('Hadir','Present')],['late',t('Terlambat','Late')]],'present')}${reasonField()}</div>${formEnd(t('Kirim permintaan','Submit request'))}</form>`);
 if(a==='correction-review'){if(!me().super)return;const x=data.corrections.find(x=>x.id===id);if(!x)return;return modal(t('Tinjau koreksi','Review correction'),`<p>${person(x.staff).name} · ${date(x.date)}</p><p class="sub">${esc(x.reason)}</p><p class="sub">${t('Usulan status','Proposed status')}: ${statusName(x.requested)}</p><div class="inline space">${btn(t('Setujui koreksi','Approve correction'),'correction-approve',`data-id="${id}"`,'primary')}${btn(t('Tutup','Close'),'close')}</div>`);}
 if(a==='correction-approve'){if(!me().super)return;const x=data.corrections.find(x=>x.id===id);if(!x||x.status!=='pending'||previewBlocked())return;x.status='approved';data.attendanceOverrides[`${x.staff}:${x.date}`]=x.requested;log(t('Koreksi kehadiran disetujui','Attendance correction approved'),x.reason);closeModal();render();return;}
 if(a==='quota'){if(!me().super)return;return modal(t('Penyesuaian saldo','Balance adjustment')+' · '+person(id).name,`<form data-form="quota" data-id="${id}">${field('adjust',t('Tambahan kuota tahunan (hari)','Additional annual days'),(data.quotaAdjust[`${id}:${day().slice(0,4)}`]??(day().startsWith('2026')?data.quotaAdjust[id]||0:0)),'number','min="0" max="30" required')}${reasonField()}${formEnd()}</form>`);}
 if(a==='comp-tab'){state.comp=value;render();return;}
 if(a==='payslip')return downloadDocument(id,'payslip',b.dataset.month||state.period);
 if(a==='staff-pay')return staffPayModal(id);
 if(a==='salary'){if(!me().super)return;const next=data.nextComp?.[id];return modal(t('Atur kompensasi','Configure compensation')+' · '+person(id).name,`<form data-form="salary" data-id="${id}"><div class="form-grid">${field('salary',t('Gaji tetap (IDR)','Base salary (IDR)'),next?.salary??data.salaries[id],'number','min="0" max="1000000000" step="1000" required')}${field('allowance',t('Tunjangan (IDR)','Allowance (IDR)'),next?.allowance??data.allowances[id],'number','min="0" max="1000000000" step="1000" required')}${field('percent',t('Bonus penjualan (%)','Sales bonus (%)'),next?.percent??data.bonusRules[id],'number','min="0" max="100" step="0.1" required')}${field('effective',t('Berlaku mulai','Effective from'),next?.effective||day().slice(0,7)+'-01','date','required min="2026-09-01"')}${reasonField()}</div><p class="scope-note">${t('Perubahan dijadwalkan mulai September atau setelahnya. Slip Juli–Agustus dipertahankan sebagai catatan historis.','Changes are scheduled from September onward. July–August payslips remain historical records.')}</p>${formEnd()}</form>`);}
 if(a==='pay-component'){if(!me().super||previewBlocked())return;const key=b.dataset.key,period=b.dataset.month||state.period;if(recordPayment118(id,period,key))log(t('Pembayaran simulasi dicatat','Simulated payment recorded'),`${person(id).name} · ${period} · ${key}`);render();staffPayModal(id);return;}
 if(a==='surprise'){if(!me().super)return;return modal(t('Buat Bonus Apresiasi','Create Appreciation Bonus'),`<form data-form="surprise"><div class="form-grid">${selectField('staff',t('Penerima','Recipient'),people.map(p=>[p.id,p.name]),'adovi')}${field('amount',t('Nominal (IDR)','Amount (IDR)'),250000,'number','min="1000" max="1000000000" step="1000" required')}${selectField('month',t('Periode','Period'),[['2026-08',month('2026-08')],['2026-07',month('2026-07')]],state.period)}${reasonField()}</div><label class="check"><input type="checkbox" name="publish">${t('Umumkan kepada penerima sekarang','Announce to the recipient now')}</label><p class="scope-note">${t('Bonus tambahan satu kali. Belum dibayar sampai pembayaran dicatat. Notifikasi tidak menampilkan nominal.','One-time additional bonus. Unpaid until payment is recorded. Notifications do not show amounts.')}</p>${formEnd(t('Simpan bonus','Save bonus'))}</form>`);}
 if(a==='publish-bonus'||a==='pay-bonus'){if(!me().super||previewBlocked())return;const x=data.surprises.find(x=>x.id===id);if(!x)return;if(a==='publish-bonus'){if(x.published)return;x.published=true;addNotification(x.staff,['Ada apresiasi untukmu','An appreciation for you'],['Rincian tersedia di Kompensasi Saya.','Details are available in My Compensation.'],'compensation');}else{if(!recordPayment118(x.staff,x.month,x.id))return;}log(a==='publish-bonus'?t('Bonus diumumkan','Bonus announced'):t('Bonus dibayar · simulasi','Bonus paid · simulation'),person(x.staff).name);render();return;}
 if(a==='role'||a==='role-new')return roleModal(a==='role-new'?'new':id);
 if(a==='assign'){if(!me().super)return;return modal(t('Ubah role','Change role')+' · '+person(id).name,`<form data-form="assign" data-id="${id}">${selectField('role',t('Role operasional','Operational role'),[['',t('Tanpa akses operasional','No operational access')],...data.roles.map(r=>[r.id,esc(splitLabel(r.name))])],data.assignments[id])}${formEnd()}</form>`);}
 if(a==='preview')return enterPreview(id);
 if(a==='preview-draft'){const f=$('form[data-form="role"]');if(!f||!actor().super)return;const v=new FormData(f);return enterPreview($('#preview-target').value,Object.fromEntries(Object.keys(permissionNames).map(k=>[k,v.get('rule-'+k)])));}
 if(a==='exit-preview'){state.preview=null;state.mode='staff';state.page='access';state.profile=null;closeModal();render();return;}
 if(a==='request-decision'){if(!me().super||previewBlocked())return;const x=data.requests.find(x=>x.id===id);if(!x||x.status!=='pending')return;if(value==='approved'&&!applyOperation(x.op))return toast(t('Status pekerjaan berubah. Permintaan perlu ditinjau ulang.','Status changed. The request needs review.'));x.status=value;addNotification(x.staff,['Keputusan permintaan tersedia','Request decision available'],['Periksa objek terkait untuk melihat hasilnya.','Check the related object for the outcome.'],'overview');log(t('Keputusan approval','Approval decision'),x.title+' · '+statusName(value));render();return;}
 if(a==='holiday'){if(!me().super)return;return modal(t('Tambah hari libur','Add holiday'),`<form data-form="holiday">${field('date',t('Tanggal','Date'),'','date','required min="2026-09-19" max="2026-12-31"')}${reasonField()}${formEnd()}</form>`);}
 if(a==='reset'){modal(t('Atur ulang simulasi?','Reset simulation?'),`<p class="sub">${t('Perubahan dalam tab ini akan kembali ke contoh awal. Tidak ada data layanan yang terpengaruh.','Changes in this tab will return to the initial examples. No service data is affected.')}</p><div class="form-actions">${btn(t('Batal','Cancel'),'close')}${btn(t('Atur ulang','Reset'),'reset-confirm','','primary')}</div>`);return;}
 if(a==='reset-confirm'){if(state.preview){toast(t('Keluar dari preview terlebih dahulu.','Exit preview first.'));return;}data=initial();state.page=state.mode==='platform'?'dashboard':'overview';state.profile=null;closeModal();render();toast(t('Simulasi kembali ke awal.','Simulation reset.'));}
}
function activityModal(){modal(t('Aktivitas Operasional','Operational Activity'),`<div class="tabs">${[['all',t('Semua','All')],['work',t('Pekerjaan','Work')],...(permission('finance')!=='none'?[['finance',t('Keuangan platform','Platform finance')]]:[])].map(([v,s])=>`<button data-action="activity-filter" data-value="${v}" class="${state.activity===v?'active':''}">${s}</button>`).join('')}</div>${activityRows(100)}<p class="scope-note">${t('Aktivitas menjelaskan perubahan; membaca daftar ini tidak menyelesaikan pekerjaan.','Activity explains changes; reading this list does not complete work.')}</p>`);}
function savePrefs(){try{localStorage.setItem('rm-v11-1-prefs',JSON.stringify({lang:state.lang,theme:state.theme}));}catch{}}
async function handleSubmit(f){if(!f.reportValidity())return;const v=new FormData(f),a=f.dataset.form,id=f.dataset.id,txt=k=>String(v.get(k)||'').trim();
 if(a==='task-action'){const x=visibleTasks().find(x=>x.id===id);if(!x||!txt('note'))return;return doOperation(x.kind,splitLabel(x.title),{type:'task',id:x.id,expected:x.stage,note:txt('note')});}
 if(a==='payment-action'){if(!txt('reason'))return;return doOperation('finance',t('Penyesuaian catatan INV-084','Note adjustment INV-084'),{type:'payment',id:'INV-084',note:txt('reason')});}
 if(a==='chat'){if(previewBlocked())return;const msg=txt('message');if(!msg)return;data.chats[state.chat].push({who:me().id,text:[msg,msg]});chatModal();return;}
 if(a==='leave'){if(previewBlocked(true))return;const start=txt('start'),end=txt('end'),days=countDays(start,end),type=txt('type');if(!Staff118.date(start)||!Staff118.date(end)||!days||start<day()||end>day().slice(0,4)+'-12-31')return feedback(t('Pilih rentang hari kerja pada tahun berjalan, mulai hari ini.','Choose working days in the current year, starting today.'));if(data.leaves.some(x=>x.staff===me().id&&['pending','approved'].includes(x.status)&&start<=x.end&&end>=x.start))return feedback(t('Tanggal bertumpang tindih dengan pengajuan yang masih aktif.','Dates overlap with an active request.'));if(type==='annual'&&days>leaveBalance(me().id).available)return feedback(t('Sisa cuti tidak cukup untuk rentang ini.','Insufficient leave balance for this range.'));data.leaves.push({id:'L-'+(data.leaves.length+1),staff:me().id,start,end,days,type,reason:txt('reason'),status:'pending'});log(t('Pengajuan cuti dikirim','Leave request submitted'),`${start} – ${end}`);closeModal();render();toast(t('Pengajuan tersimpan. Saldo tahunan dicadangkan jika berlaku.','Request saved. Annual balance reserved where applicable.'));return;}
 if(a==='leave-reject'){if(!me().super||previewBlocked())return;const x=data.leaves.find(x=>x.id===id);if(!x||x.status!=='pending')return;x.status='rejected';x.reason+=' · '+txt('reason');log(t('Pengajuan cuti ditolak','Leave request declined'),txt('reason'));addNotification(x.staff,['Keputusan cuti tersedia','Leave decision available'],['Lihat alasan pada riwayat pengajuan.','See the reason in your request history.'],'attendance');}
 if(a==='attendance-correction'){if(previewBlocked(true))return;const d=txt('date');if(d<'2026-07-01'||d>'2026-09-19')return feedback(t('Tanggal di luar periode demo.','Date outside the demo period.'));data.corrections.push({id:'K'+(data.corrections.length+1),staff:me().id,date:d,requested:txt('status'),reason:txt('reason'),status:'pending'});log(t('Koreksi kehadiran diajukan','Attendance correction requested'),txt('reason'));}
 if(a==='personal'){if(id!==me().id&&!me().super)return;if(previewBlocked())return;const photo=v.get('photo');if(photo?.size>2*1024*1024)return feedback(t('Foto maksimal 2 MB.','Photo maximum is 2 MB.'));if(photo?.size&&!['image/png','image/jpeg','image/webp'].includes(photo.type))return feedback(t('Gunakan PNG, JPEG, atau WebP.','Use PNG, JPEG or WebP.'));data.profiles[id].phone=txt('phone');data.profiles[id].location=txt('location');if(photo?.size)data.profiles[id].photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(photo);});log(t('Profil diperbarui','Profile updated'),person(id).name);}
 if(a==='data-issue'){if(previewBlocked(true))return;if(!canTeam()&&id!==me().id)return;data.issues.push({id:'I'+(data.issues.length+1),staff:id,period:state.period,reason:txt('reason'),status:'pending'});log(t('Catatan data kinerja dikirim','Performance-data issue submitted'),txt('reason'));}
 if(['role','assign','policy','quota','salary','surprise','holiday'].includes(a)){if(!me().super||previewBlocked())return;
  if(a==='role'){const rules=Object.fromEntries(Object.keys(permissionNames).map(k=>[k,txt('rule-'+k)]));if(data.roles.some(r=>r.id!==id&&r.name.toLowerCase()===txt('name').toLowerCase()))return feedback(t('Nama role sudah digunakan.','Role name already used.'));if(id==='new')data.roles.push({id:'role-'+Date.now(),name:txt('name'),rules});else{const r=data.roles.find(r=>r.id===id);r.name=txt('name');r.rules=rules;}log(t('Role diperbarui','Role updated'),txt('name'));}
  if(a==='assign'){if(person(id)?.super)return;data.assignments[id]=txt('role');log(t('Penugasan role diperbarui','Role assignment updated'),person(id).name);}
  if(a==='quota'){const n=Number(v.get('adjust'));if(!Number.isFinite(n)||n<0||n>30)return;saveQuota118(id,n);log(t('Kuota tambahan diperbarui','Additional allowance updated'),person(id).name+' · '+txt('reason'));}
  if(a==='policy'){const days=v.getAll('days').map(Number),quota=Number(v.get('quota'));if(!days.length||txt('end')<=txt('start'))return feedback(t('Pilih hari kerja dan jam selesai setelah jam masuk.','Choose working days and an end time after the start.'));if(quota<12||people.some(p=>{const q=leaveBalance(p.id);return quota+(data.quotaAdjust[p.id]||0)<q.used+q.scheduled+q.pending;}))return feedback(t('Kuota tidak boleh di bawah hak minimum atau saldo yang sudah digunakan/dicadangkan.','Allowance cannot fall below the baseline or used/reserved days.'));data.policy={...data.policy,quota,carry:Number(v.get('carry')),notice:Number(v.get('notice')),grace:Number(v.get('grace')),start:txt('start'),end:txt('end'),effective:txt('effective'),days};log(t('Kebijakan diperbarui; pengajuan lama tidak dihitung ulang','Policy updated; existing requests not recalculated'),txt('reason'));}
  if(a==='salary'){saveCompensation118(id,{salary:Number(v.get('salary')),allowance:Number(v.get('allowance')),percent:Number(v.get('percent')),effective:txt('effective')});log(t('Kompensasi mendatang dijadwalkan','Future compensation scheduled'),person(id).name+' · '+txt('effective')+' · '+txt('reason'));}
  if(a==='surprise'){const target=txt('staff'),note=txt('reason'),published=v.has('publish');data.surprises.push({id:'B-'+(data.surprises.length+1),staff:target,month:txt('month'),amount:Number(v.get('amount')),note:[note,note],published,paid:false});if(published)addNotification(target,['Ada apresiasi untukmu','An appreciation for you'],['Rinciannya tersedia di Kompensasi Saya.','Details are available in My Compensation.'],'compensation');log(t('Bonus Apresiasi dibuat','Appreciation Bonus created'),person(target).name);}
  if(a==='holiday'){const d=txt('date');if(!data.holidays.includes(d))data.holidays.push(d);log(t('Hari libur ditambahkan','Holiday added'),d+' · '+txt('reason'));}
 }
 closeModal();render();toast(t('Tersimpan dalam simulasi.','Saved in the simulation.'));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)Promise.resolve(handleAction(b)).catch(error=>{console.error(error);toast(t('Tindakan belum berhasil. Coba kembali.','Action unsuccessful. Please try again.'));});});
document.addEventListener('submit',e=>{if(e.target.matches('form[data-form]')){e.preventDefault();Promise.resolve(handleSubmit(e.target)).catch(error=>{console.error(error);feedback(t('Data belum tersimpan. Coba kembali.','Data was not saved. Please try again.'));});}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')searchResults(e.target.value);if(e.target.closest('form[data-form="leave"]'))estimateLeave();});
document.addEventListener('change',e=>{if(e.target.id==='demo-user'&&!state.preview){state.user=e.target.value;state.profile=null;state.scope='mine';state.comp='mine';state.attendance='mine';state.page=state.mode==='platform'?'dashboard':'overview';closeModal();render();window.scrollTo({top:0});}if(e.target.id==='period'){state.period=e.target.value;render();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#dialog').open)searchModal();}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
